CREATE TABLE default.libp2p_peer_local\n(\n    `unique_key` Int64 COMMENT 'Unique identifier for each record, seahash of peer_id + meta_network_name',\n    `updated_date_time` DateTime COMMENT 'Timestamp when the record was last updated' CODEC(DoubleDelta, ZSTD(1)),\n    `peer_id` String COMMENT 'Peer ID' CODEC(ZSTD(1)),\n    `meta_network_id` Int32 COMMENT 'Ethereum network ID' CODEC(DoubleDelta, ZSTD(1)),\n    `meta_network_name` LowCardinality(String) COMMENT 'Ethereum network name'\n)\nENGINE = ReplicatedReplacingMergeTree(\'/clickhouse/{installation}/{cluster}/tables/{shard}/default/libp2p_peer_local\', \'{replica}\', updated_date_time)\nORDER BY unique_key\nSETTINGS index_granularity = 8192\n
